<template><div class="qne-page"><header><div><p>QGAUSS / OPEN A NEW POSSIBILITY</p><h1>{{entry?menuLabel(entry,currentLang):nt('功能导航')}}</h1><small v-if="entry">{{menuHint(entry,currentLang)}}</small></div><div><button type="button" class="qne-button" :disabled="loading" @click="load"><ClientIcon name="refresh"/>{{nt('重新核对入口')}}</button><a v-if="entry?.url" :href="entry.url" target="_blank" rel="noopener noreferrer" class="qne-button qne-primary"><ClientIcon name="arrowUpRight"/>{{nt('在新窗口打开')}}</a><router-link v-else to="/chat" class="qne-button">{{nt('返回创作空间')}}</router-link></div></header><div v-if="error" class="qne-unavailable" role="status"><ClientIcon name="apps"/><h2>{{nt(error)}}</h2><router-link v-if="signIn" :to="{path:'/login',query:{redirect:route.fullPath}}" class="qne-button qne-primary">{{nt('去登录')}}</router-link></div><div v-else-if="loading&&!entry" class="qne-loading"><BrandLoader :size="50"/></div><template v-else-if="entry?.kind==='embed'"><p class="qne-note">{{nt('若内容没有显示，可以在新窗口打开。')}}</p><div class="qne-canvas"><iframe v-if="target" :key="frameKey" :src="target.src" :sandbox="target.sandbox" :title="menuLabel(entry,currentLang)" referrerpolicy="no-referrer" allow="camera 'none'; microphone 'none'; geolocation 'none'; payment 'none'; clipboard-read 'none'; clipboard-write 'none'" @load="frameLoading=false" @error="frameLoading=false;error='这个导航入口暂时不可用。'"></iframe><div v-if="frameLoading" class="qne-frame-loading"><BrandLoader :size="38" :text="nt('正在展开新画布')"/></div></div></template><div v-else-if="entry?.kind==='external'" class="qne-external"><ClientIcon name="globe"/><small>{{nt('外部站点')}}</small><h2>{{menuLabel(entry,currentLang)}}</h2><p>{{menuHint(entry,currentLang)}}</p><a :href="entry.url" target="_blank" rel="noopener noreferrer" class="qne-button qne-primary">{{nt('在新窗口打开')}}<ClientIcon name="arrowUpRight"/></a></div></div></template>
<script setup>
import{onBeforeUnmount,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{api}from'../api/client.js';import{useAuth}from'../stores/auth.js';import{currentLang}from'../i18n/index.js';import{navigationText}from'../i18n/navigation-messages.js';import{menuEntry,menuFrameTarget,menuLabel,menuHint}from'../lib/navigation.js';import{subscribeNavigationChanges}from'../lib/navigation-changes.js';import ClientIcon from'../components/reference/ClientIcon.vue';import BrandLoader from'../components/design/BrandLoader.vue';import'../components/navigation/menu-entry.css';
const route=useRoute(),router=useRouter(),auth=useAuth(),entry=ref(null),target=ref(null),frameKey=ref(0),loading=ref(false),frameLoading=ref(false),error=ref(''),signIn=ref(false),media=window.matchMedia('(max-width:760px)'),nt=value=>navigationText(currentLang.value,value);let alive=true,epoch=0,request=null;
async function load(){const id=String(route.params.id||''),owner=auth.user?.id||'',identity=auth.identityRevision,n=++epoch;request?.abort();request=new AbortController();loading.value=true;error.value='';signIn.value=false;const current=()=>alive&&n===epoch&&route.params.id===id&&(auth.user?.id||'')===owner&&auth.identityRevision===identity;try{const row=menuEntry(await api.get('/menus/entries/'+encodeURIComponent(id)+'?platform='+(media.matches?'mobile':'desktop'),{signal:request.signal}),id);if(!current())return;if(row.kind==='internal'){entry.value=row;target.value=null;await router.replace(row.path);return;}const next=row.kind==='embed'?menuFrameTarget(row,location.origin):null;entry.value=row;if(next?.src!==target.value?.src){target.value=next;frameKey.value++;frameLoading.value=!!next;}}catch(e){if(current()){entry.value=null;target.value=null;frameLoading.value=false;signIn.value=e.status===401;error.value=signIn.value?'请先登录，再打开这个入口。':e.status===404?'此入口已收起或可见范围发生变化。':e.message||'这个导航入口暂时不可用。';}}finally{if(current())loading.value=false;}}
watch(()=>[route.params.id,auth.user?.id,auth.user?.role,auth.identityRevision],()=>{entry.value=null;target.value=null;frameLoading.value=false;void load();},{immediate:true,flush:'sync'});const updateDevice=()=>{entry.value=null;target.value=null;void load();};media.addEventListener('change',updateDevice);const stop=subscribeNavigationChanges(()=>load());onBeforeUnmount(()=>{alive=false;epoch++;request?.abort();stop();media.removeEventListener('change',updateDevice);});
</script>
